from pathlib import Path
root = Path('/mnt/data/electric-power-inspection-robot')
print("root exists:", root.exists())
print("git exists:", (root/'.git').exists())
if root.exists():
    exts = {'.png','.jpg','.jpeg','.gif','.svg','.webp','.bmp','.tif','.tiff','.ico','.pgm','.ppm','.pnm','.jfif','.avif','.heic','.heif'}
    imgs = [p for p in root.rglob('*') if p.is_file() and p.suffix.lower() in exts and '.git' not in p.parts]
    print("count", len(imgs))
    for p in imgs[:200]:
        print(p.relative_to(root))

